import React, { useState } from "react";
import { motion } from "framer-motion";
import axios from "axios";
import { UploadCloud, CheckCircle2, XCircle } from "lucide-react";

const Interview = () => {
  const [video, setVideo] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [message, setMessage] = useState("");

  const handleFileChange = (e) => setVideo(e.target.files[0]);

  const handleUpload = async () => {
    if (!video) return setMessage("Please select a video first!");
    const formData = new FormData();
    formData.append("file", video);
    try {
      setUploading(true);
      await axios.post("http://localhost:8080/api/video/upload", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      setMessage("✅ Video uploaded successfully!");
    } catch {
      setMessage("❌ Upload failed!");
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col justify-center items-center bg-gradient-to-br from-white to-gray-100 p-8">
      <motion.div
        className="bg-white rounded-xl shadow-lg p-10 max-w-lg w-full text-center border border-gray-200"
        initial={{ opacity: 0, y: 40 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        <h1 className="text-3xl font-serif text-primary mb-6">
          Upload Your Interview Video
        </h1>

        <label className="flex flex-col items-center justify-center border-2 border-dashed border-primary/50 rounded-lg py-10 cursor-pointer hover:bg-gray-50 transition">
          <UploadCloud className="w-12 h-12 text-secondary mb-2" />
          <span className="text-gray-600">{video ? video.name : "Click to choose video"}</span>
          <input type="file" accept="video/*" onChange={handleFileChange} className="hidden" />
        </label>

        <button
          onClick={handleUpload}
          disabled={uploading}
          className="mt-6 bg-secondary text-white px-6 py-3 rounded-md hover:bg-primary transition"
        >
          {uploading ? "Uploading..." : "Upload"}
        </button>

        {message && (
          <p className="mt-4 text-lg font-medium text-gray-700">{message}</p>
        )}
      </motion.div>
    </div>
  );
};

export default Interview;
